            200 to longArrayOf(112900L, 113400L, 113900L, 114300L, 114900L, 115500L, 116100L, 116800L, 117500L, 118100L, 119700L, 121200L, 122500L, 124700L, 126800L, 128900L, 131600L, 134200L, 136800L, 146200L, 155800L, 164900L, 600000L)
        )
    )

    private fun tierIndex(thresholds: LongArray, timeMs: Long): Int =
        thresholds.indexOfFirst { timeMs <= it }.takeIf { it >= 0 }
            ?: thresholds.lastIndex

    fun trackTier(trackId: String, mode: Int, timeMs: Long): Int? =
        trackThresholds[trackId]?.get(mode)?.let { tierIndex(it, timeMs) }

    fun trackLadder(trackId: String, mode: Int): LongArray? =
        trackThresholds[trackId]?.get(mode)?.copyOf()

    private fun totalThresholds(mode: Int, trackIds: Set<String>?): LongArray =
        if (trackIds == null) requireNotNull(totalThresholds[mode])
        else LongArray(tierLabels.size) { tier ->
            trackIds.sumOf { trackId -> trackThresholds[trackId]?.get(mode)?.get(tier) ?: UNPLAYED_FALLBACK_MS }
        }

    fun totalTier(mode: Int, totalMs: Long, trackIds: Set<String>? = null): Int =
        tierIndex(totalThresholds(mode, trackIds), totalMs)

    fun nextTotalTierDeltaMs(mode: Int, totalMs: Long, trackIds: Set<String>? = null): Long? {
        val thresholds = totalThresholds(mode, trackIds)
        val tier = tierIndex(thresholds, totalMs)
        if (tier == 0) return null
        return (totalMs - thresholds[tier - 1])
            .coerceAtLeast(0L)
    }

    private val packagedTrackThresholds = trackThresholds
    private val packagedTotalThresholds = totalThresholds

    /** Back to the thresholds packaged in the app; for tests that apply a snapshot of their own. */
    internal fun resetToPackagedBaseline() {
        trackThresholds = packagedTrackThresholds
        totalThresholds = packagedTotalThresholds
        usesLiveWorldRecords = false
    }

    /** True once a complete current World Record snapshot is the baseline (ADR-0169). */
    @Volatile
    var usesLiveWorldRecords: Boolean = false
        private set

    fun applyWorldRecords(records: List<AndroidWorldRecord>): Boolean =
        applyWorldRecordTimes(records.map { Triple(it.mode, it.trackId, it.totalTimeMs) })

    /** (mode, trackId, World Record ms) for all 192 cells; anything incomplete keeps the current baseline. */
    fun applyWorldRecordTimes(records: List<Triple<Int, String, Long>>): Boolean {
        if (records.size != 192) return false
        val worldRecords = records.associate { (mode, trackId, totalTimeMs) -> "$mode|$trackId" to totalTimeMs }
        if (worldRecords.size != 192) return false
        val next = mutableMapOf<String, Map<Int, LongArray>>()
        for (trackId in trackThresholds.keys) {
            val rows = mutableMapOf<Int, LongArray>()
            for (mode in listOf(150, 200)) {
                val wr = worldRecords["$mode|$trackId"] ?: return false
                rows[mode] = (masteryWrRatios.map { kotlin.math.round(wr * it / 100.0).toLong() * 100L } + UNPLAYED_FALLBACK_MS).toLongArray()
            }
            next[trackId] = rows
        }
        trackThresholds = next
        totalThresholds = listOf(150, 200).associateWith { mode ->
            LongArray(23) { tier -> next.values.sumOf { requireNotNull(it[mode])[tier] } }
        }
        usesLiveWorldRecords = true
        return true
    }
}
